-- Server-authoritative double-six domino engine v2.
-- Private hands and boneyard never enter game_rooms.game_state.
-- Start/restart deals are generated by the authenticated Edge Function.
begin;

create table if not exists public.game_room_private_state (
  room_id uuid primary key references public.game_rooms(id) on delete cascade,
  secret_state jsonb not null,
  created_at timestamptz not null default pg_catalog.clock_timestamp(),
  updated_at timestamptz not null default pg_catalog.clock_timestamp()
);

create table if not exists public.game_room_engine_events (
  id bigint generated always as identity primary key,
  room_id uuid not null references public.game_rooms(id) on delete cascade,
  actor_id uuid not null,
  event_type text not null,
  event_payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default pg_catalog.clock_timestamp()
);

create index if not exists game_room_engine_events_room_created_idx
  on public.game_room_engine_events(room_id,created_at,id);

alter table public.game_room_engine_events
  drop constraint if exists game_room_engine_events_event_type_check;
alter table public.game_room_engine_events
  add constraint game_room_engine_events_event_type_check
  check(event_type in (
    'number_started','number_restarted','number_guess',
    'most_started','most_vote','most_question','most_finished','most_restarted','most_player_left',
    'quiz_started','quiz_answer','quiz_question','quiz_finished','quiz_restarted','quiz_player_left',
    'yesno_started','yesno_answer','yesno_question','yesno_finished','yesno_restarted','yesno_player_left',
    'liar_started','liar_hint','liar_vote','liar_finished','liar_restarted','liar_player_left',
    'snakes_started','snakes_roll','snakes_finished','snakes_restarted','snakes_player_left',
    'domino_started','domino_play','domino_draw','domino_pass','domino_finished','domino_restarted','domino_player_left'
  ));

alter table public.game_room_private_state enable row level security;
alter table public.game_room_engine_events enable row level security;
revoke all on public.game_room_private_state from public,anon,authenticated;
revoke all on public.game_room_engine_events from public,anon,authenticated;
grant all on public.game_room_private_state to service_role;
grant all on public.game_room_engine_events to service_role;
grant usage,select on sequence public.game_room_engine_events_id_seq to service_role;

create or replace function public.engine_v2_start_domino_game(
  p_room_id uuid,
  p_actor_id uuid,
  p_deal jsonb,
  p_boneyard jsonb,
  p_starting_player uuid,
  p_expected_updated_at timestamptz,
  p_is_restart boolean default false
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_player record;
  v_tile jsonb;
  v_hand jsonb;
  v_seen jsonb:='{}'::jsonb;
  v_hands jsonb;
  v_hand_counts jsonb;
  v_order jsonb;
  v_total integer;
  v_hand_size integer;
  v_tile_a integer;
  v_tile_b integer;
  v_tile_key text;
  v_deck_count integer:=0;
  v_boneyard_count integer;
  v_state jsonb;
  v_secret jsonb;
  v_round integer;
  v_status text;
begin
  if coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'
  ) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_starting_player is null
     or p_expected_updated_at is null
     or jsonb_typeof(p_deal) is distinct from 'object'
     or jsonb_typeof(p_boneyard) is distinct from 'array' then
    raise exception 'بيانات توزيع الدومينو غير صالحة.' using errcode='22023';
  end if;

  select * into v_room
  from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة ثانية.' using errcode='40001';
  end if;
  if v_room.host_id is distinct from p_actor_id then
    raise exception 'بدء أو إعادة الدومينو من صلاحية المضيف فقط.' using errcode='42501';
  end if;
  if not exists(
    select 1 from public.game_room_players p
    where p.room_id=p_room_id and p.user_id=p_actor_id
  ) then
    raise exception 'المضيف لم يعد عضواً في الغرفة.' using errcode='42501';
  end if;

  if p_is_restart then
    if v_room.engine_version<>2 or v_room.game_key<>'domino' or v_room.status<>'finished' then
      raise exception 'لا يمكن إعادة الدومينو بهذه الحالة.';
    end if;
  else
    if v_room.engine_version<>2 or v_room.game_key<>'domino' or v_room.status<>'waiting' then
      raise exception 'هذه الغرفة ليست جاهزة لمحرك الدومينو.';
    end if;
  end if;

  select count(*)::integer into v_total
  from public.game_room_players p where p.room_id=p_room_id;
  if v_total not between 2 and 4 or v_total>v_room.max_players then
    raise exception 'عدد اللاعبين لا يناسب الدومينو.';
  end if;
  v_hand_size:=case when v_total=2 then 7 else 5 end;

  if (select count(*) from jsonb_object_keys(p_deal))<>v_total then
    raise exception 'توزيع القطع لا يطابق عدد اللاعبين.';
  end if;
  if jsonb_array_length(p_boneyard)<>28-(v_total*v_hand_size) then
    raise exception 'عدد قطع السحب في التوزيع غير صحيح.';
  end if;

  v_hands:='{}'::jsonb;
  v_hand_counts:='{}'::jsonb;
  v_order:='[]'::jsonb;
  for v_player in
    select p.user_id,p.seat
    from public.game_room_players p
    where p.room_id=p_room_id
    order by p.seat
  loop
    v_hand:=p_deal->v_player.user_id::text;
    if v_hand is null or jsonb_typeof(v_hand)<>'array'
       or jsonb_array_length(v_hand)<>v_hand_size then
      raise exception 'حجم يد اللاعب غير صحيح.';
    end if;

    for v_tile in select value from jsonb_array_elements(v_hand)
    loop
      if jsonb_typeof(v_tile)<>'array' or jsonb_array_length(v_tile)<>2
         or jsonb_typeof(v_tile->0)<>'number' or jsonb_typeof(v_tile->1)<>'number'
         or (v_tile->>0)!~'^[0-6]$' or (v_tile->>1)!~'^[0-6]$' then
        raise exception 'قطعة دومينو غير صالحة.';
      end if;
      v_tile_a:=(v_tile->>0)::integer;
      v_tile_b:=(v_tile->>1)::integer;
      if v_tile_a>v_tile_b then
        raise exception 'ترتيب أرقام قطعة الدومينو غير صالح.';
      end if;
      v_tile_key:=v_tile_a::text||':'||v_tile_b::text;
      if v_seen ? v_tile_key then
        raise exception 'توجد قطعة دومينو مكررة.';
      end if;
      v_seen:=v_seen||jsonb_build_object(v_tile_key,true);
      v_deck_count:=v_deck_count+1;
    end loop;

    v_hands:=v_hands||jsonb_build_object(v_player.user_id::text,v_hand);
    v_hand_counts:=v_hand_counts||jsonb_build_object(v_player.user_id::text,v_hand_size);
    v_order:=v_order||jsonb_build_array(v_player.user_id::text);
  end loop;

  for v_tile in select value from jsonb_array_elements(p_boneyard)
  loop
    if jsonb_typeof(v_tile)<>'array' or jsonb_array_length(v_tile)<>2
       or jsonb_typeof(v_tile->0)<>'number' or jsonb_typeof(v_tile->1)<>'number'
       or (v_tile->>0)!~'^[0-6]$' or (v_tile->>1)!~'^[0-6]$' then
      raise exception 'قطعة في كومة السحب غير صالحة.';
    end if;
    v_tile_a:=(v_tile->>0)::integer;
    v_tile_b:=(v_tile->>1)::integer;
    if v_tile_a>v_tile_b then
      raise exception 'ترتيب قطع كومة السحب غير صالح.';
    end if;
    v_tile_key:=v_tile_a::text||':'||v_tile_b::text;
    if v_seen ? v_tile_key then
      raise exception 'توجد قطعة دومينو مكررة.';
    end if;
    v_seen:=v_seen||jsonb_build_object(v_tile_key,true);
    v_deck_count:=v_deck_count+1;
  end loop;

  if v_deck_count<>28 or (select count(*) from jsonb_object_keys(v_seen))<>28 then
    raise exception 'مجموعة الدومينو يجب أن تحتوي ٢٨ قطعة مختلفة بالضبط.';
  end if;
  if not exists(
    select 1 from public.game_room_players p
    where p.room_id=p_room_id and p.user_id=p_starting_player
  ) then
    raise exception 'اللاعب الذي يبدأ غير موجود في الغرفة.';
  end if;
  if not exists(
    select 1 from jsonb_array_elements(v_hands->p_starting_player::text) t(value)
    where value=jsonb_build_array(6,6)
  ) then
    raise exception 'يجب أن يبدأ حامل الدبل ستة.';
  end if;
  if p_is_restart then
    v_round:=coalesce((v_room.game_state->>'round')::integer,1)+1;
  else
    v_round:=1;
  end if;

  v_boneyard_count:=jsonb_array_length(p_boneyard);
  v_secret:=jsonb_build_object(
    'game','domino',
    'hands',v_hands,
    'boneyard',p_boneyard,
    'player_order',v_order,
    'starting_player',p_starting_player::text,
    'opening_tile',jsonb_build_array(6,6),
    'chain','[]'::jsonb,
    'left_end',null,
    'right_end',null,
    'pass_count',0,
    'move_count',0
  );
  v_state:=jsonb_build_object(
    'phase','playing',
    'round',v_round,
    'turn',(select count(*)::integer from public.game_room_players prior where prior.room_id=p_room_id and prior.seat < (select starter.seat from public.game_room_players starter where starter.room_id=p_room_id and starter.user_id=p_starting_player)),
    'scores',coalesce(v_room.game_state->'scores','{}'::jsonb),
    'feed',jsonb_build_array('بدأت لعبة الدومينو بالدبل ستة.'),
    'board',jsonb_build_object(
      'chain','[]'::jsonb,
      'left_end',null,
      'right_end',null,
      'current_player_id',p_starting_player::text,
      'player_order',v_order,
      'turn_index',(select count(*)::integer from public.game_room_players prior where prior.room_id=p_room_id and prior.seat < (select starter.seat from public.game_room_players starter where starter.room_id=p_room_id and starter.user_id=p_starting_player)),
      'hand_counts',v_hand_counts,
      'boneyard_count',v_boneyard_count,
      'pass_count',0,
      'move_count',0,
      'opening_required',true,
      'last_move',null,
      'winner_ids','[]'::jsonb,
      'pip_totals','{}'::jsonb,
      'finish_reason',null
    )
  );

  insert into public.game_room_private_state(room_id,secret_state)
  values(p_room_id,v_secret)
  on conflict(room_id) do update
    set secret_state=excluded.secret_state,updated_at=pg_catalog.clock_timestamp();

  update public.game_rooms
  set engine_version=2,status='playing',game_state=v_state,
      game_started_at=pg_catalog.clock_timestamp(),
      updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(
    p_room_id,p_actor_id,
    case when p_is_restart then 'domino_restarted' else 'domino_started' end,
    jsonb_build_object('players',v_total,'hand_size',v_hand_size,'boneyard_count',v_boneyard_count)
  );
  return v_room;
end;
$function$;

create or replace function public.engine_v2_get_domino_hand(
  p_room_id uuid,
  p_actor_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_secret jsonb;
  v_hand jsonb;
  v_board jsonb;
  v_player text;
begin
  if coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'
  ) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null then raise exception 'بيانات اللاعب غير صالحة.'; end if;

  select * into v_room from public.game_rooms where id=p_room_id for share;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.engine_version<>2 or v_room.game_key<>'domino' or v_room.status<>'playing' then
    raise exception 'محرك الدومينو غير نشط.';
  end if;
  if not exists(
    select 1 from public.game_room_players p
    where p.room_id=p_room_id and p.user_id=p_actor_id
  ) then
    raise exception 'لست عضواً في هذه الغرفة.' using errcode='42501';
  end if;

  select secret_state into v_secret
  from public.game_room_private_state where room_id=p_room_id for share;
  if not found or v_secret->>'game' is distinct from 'domino' then
    raise exception 'يد الدومينو غير متاحة.';
  end if;

  v_hand:=v_secret->'hands'->p_actor_id::text;
  if v_hand is null then raise exception 'لا توجد يد لهذا اللاعب.'; end if;
  v_board:=coalesce(v_room.game_state->'board','{}'::jsonb);
  v_player:=v_board->>'current_player_id';

  return jsonb_build_object(
    'tiles',v_hand,
    'is_current_turn',v_player=p_actor_id::text,
    'opening_tile',case
      when jsonb_array_length(coalesce(v_board->'chain','[]'::jsonb))=0
       and v_secret->>'starting_player'=p_actor_id::text
      then v_secret->'opening_tile'
      else null
    end
  );
end;
$function$;

create or replace function public.engine_v2_play_domino(
  p_room_id uuid,
  p_actor_id uuid,
  p_tile_a integer,
  p_tile_b integer,
  p_side text,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_secret jsonb;
  v_hand jsonb;
  v_new_hand jsonb;
  v_chain jsonb;
  v_oriented jsonb;
  v_board jsonb;
  v_state jsonb;
  v_order jsonb;
  v_current text;
  v_turn_index integer;
  v_total integer;
  v_index bigint;
  v_item record;
  v_left integer;
  v_right integer;
  v_new_left integer;
  v_new_right integer;
  v_side text;
  v_count integer;
  v_counts jsonb;
  v_scores jsonb;
  v_score integer;
  v_pips jsonb:='{}'::jsonb;
  v_player record;
  v_sum integer;
  v_finished boolean:=false;
  v_feed jsonb;
  v_name text;
begin
  if coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'
  ) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_tile_a is null or p_tile_b is null
     or p_tile_a not between 0 and 6 or p_tile_b not between 0 and 6
     or p_tile_a>p_tile_b or p_side is null or p_side not in ('left','right','auto')
     or p_expected_updated_at is null then
    raise exception 'بيانات قطعة الدومينو غير صالحة.' using errcode='22023';
  end if;

  select * into v_room from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة ثانية.' using errcode='40001';
  end if;
  if v_room.engine_version<>2 or v_room.game_key<>'domino' or v_room.status<>'playing' then
    raise exception 'محرك الدومينو غير نشط.';
  end if;
  if not exists(
    select 1 from public.game_room_players p
    where p.room_id=p_room_id and p.user_id=p_actor_id
  ) then
    raise exception 'لست عضواً في هذه الغرفة.' using errcode='42501';
  end if;

  v_board:=coalesce(v_room.game_state->'board','{}'::jsonb);
  v_current:=v_board->>'current_player_id';
  if v_current is distinct from p_actor_id::text then
    raise exception 'مو دورك بعد.' using errcode='42501';
  end if;
  select secret_state into v_secret
  from public.game_room_private_state where room_id=p_room_id for update;
  if not found then raise exception 'حالة الدومينو الخاصة غير متاحة.'; end if;
  v_hand:=v_secret->'hands'->p_actor_id::text;
  if v_hand is null then raise exception 'لا توجد يد لهذا اللاعب.'; end if;

  v_index:=null;
  for v_item in
    select value,ordinality
    from jsonb_array_elements(v_hand) with ordinality as h(value,ordinality)
  loop
    if ((v_item.value->>0)::integer=p_tile_a and (v_item.value->>1)::integer=p_tile_b)
       or ((v_item.value->>0)::integer=p_tile_b and (v_item.value->>1)::integer=p_tile_a) then
      v_index:=v_item.ordinality;
      exit;
    end if;
  end loop;
  if v_index is null then raise exception 'هاي القطعة مو ضمن يدك.' using errcode='42501'; end if;

  v_chain:=coalesce(v_secret->'chain','[]'::jsonb);
  v_side:=p_side;
  if jsonb_array_length(v_chain)=0 then
    if v_secret->>'starting_player' is distinct from p_actor_id::text
       or p_tile_a<>6 or p_tile_b<>6 then
      raise exception 'أول قطعة لازم تكون الدبل ستة من اللاعب الذي يبدأ.';
    end if;
    v_oriented:=jsonb_build_array(6,6);
    v_new_left:=6;
    v_new_right:=6;
    v_side:='right';
  else
    v_left:=(v_secret->>'left_end')::integer;
    v_right:=(v_secret->>'right_end')::integer;

    if p_side in ('right','auto') then
      if p_tile_a=v_right then
        v_oriented:=jsonb_build_array(p_tile_a,p_tile_b);
        v_new_right:=p_tile_b;
        v_side:='right';
      elsif p_tile_b=v_right then
        v_oriented:=jsonb_build_array(p_tile_b,p_tile_a);
        v_new_right:=p_tile_a;
        v_side:='right';
      end if;
    end if;
    if v_oriented is null and p_side in ('left','auto') then
      if p_tile_b=v_left then
        v_oriented:=jsonb_build_array(p_tile_a,p_tile_b);
        v_new_left:=p_tile_a;
        v_side:='left';
      elsif p_tile_a=v_left then
        v_oriented:=jsonb_build_array(p_tile_b,p_tile_a);
        v_new_left:=p_tile_b;
        v_side:='left';
      end if;
    end if;
    if v_oriented is null then
      raise exception 'القطعة لا تطابق الطرف المختار من السلسلة.';
    end if;
    if v_side='right' then v_new_left:=v_left; else v_new_right:=v_right; end if;
  end if;

  select p.display_name into v_name
  from public.game_room_players p where p.room_id=p_room_id and p.user_id=p_actor_id;

  select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb)
  into v_new_hand
  from jsonb_array_elements(v_hand) with ordinality as h(value,ordinality)
  where ordinality<>v_index;

  if v_side='left' and jsonb_array_length(v_chain)>0 then
    v_chain:=jsonb_build_array(v_oriented)||v_chain;
  else
    v_chain:=v_chain||jsonb_build_array(v_oriented);
  end if;
  v_count:=jsonb_array_length(v_new_hand);
  v_counts:=jsonb_set(coalesce(v_board->'hand_counts','{}'::jsonb),array[p_actor_id::text],to_jsonb(v_count),true);

  v_turn_index:=coalesce((v_board->>'turn_index')::integer,0);
  v_order:=coalesce(v_secret->'player_order','[]'::jsonb);
  v_total:=jsonb_array_length(v_order);
  if v_total not between 2 and 4 or v_turn_index<0 or v_turn_index>=v_total then
    raise exception 'ترتيب أدوار الدومينو غير صالح.';
  end if;
  v_finished:=v_count=0;
  v_scores:=coalesce(v_room.game_state->'scores','{}'::jsonb);
  if v_finished then
    v_score:=coalesce((v_scores->>p_actor_id::text)::integer,0)+1;
    v_scores:=jsonb_set(v_scores,array[p_actor_id::text],to_jsonb(v_score),true);
    for v_player in
      select p.user_id from public.game_room_players p where p.room_id=p_room_id
    loop
      select coalesce(sum((piece.value->>0)::integer+(piece.value->>1)::integer),0)::integer
      into v_sum
      from jsonb_array_elements(v_secret->'hands'->v_player.user_id::text) as piece(value);
      if v_player.user_id=p_actor_id then v_sum:=0; end if;
      v_pips:=v_pips||jsonb_build_object(v_player.user_id::text,v_sum);
    end loop;
  end if;

  v_board:=v_board||jsonb_build_object(
    'chain',v_chain,
    'left_end',v_new_left,
    'right_end',v_new_right,
    'current_player_id',case when v_finished then null else v_order->>((v_turn_index+1)%v_total) end,
    'turn_index',case when v_finished then v_turn_index else (v_turn_index+1)%v_total end,
    'hand_counts',v_counts,
    'pass_count',0,
    'move_count',coalesce((v_board->>'move_count')::integer,0)+1,
    'opening_required',false,
    'last_move',jsonb_build_object(
      'player_id',p_actor_id::text,'tile',v_oriented,'side',v_side
    ),
    'winner_ids',case when v_finished then jsonb_build_array(p_actor_id::text) else '[]'::jsonb end,
    'pip_totals',case when v_finished then v_pips else coalesce(v_board->'pip_totals','{}'::jsonb) end,
    'finish_reason',case when v_finished then 'empty_hand' else null end
  );
  v_feed:=coalesce(v_room.game_state->'feed','[]'::jsonb)
    ||jsonb_build_array(v_name||' لعب قطعة '||p_tile_a||'|'||p_tile_b||'.');
  if v_finished then v_feed:=v_feed||jsonb_build_array(v_name||' أنهى كل قطعه وفاز!'); end if;
  v_state:=v_room.game_state||jsonb_build_object(
    'phase',case when v_finished then 'finished' else 'playing' end,
    'turn',case when v_finished then v_turn_index else (v_turn_index+1)%v_total end,
    'scores',v_scores,'board',v_board,'feed',v_feed
  );

  v_secret:=jsonb_set(v_secret,array['hands',p_actor_id::text],v_new_hand,true);
  v_secret:=jsonb_set(v_secret,'{chain}',v_chain,true);
  v_secret:=jsonb_set(v_secret,'{left_end}',to_jsonb(v_new_left),true);
  v_secret:=jsonb_set(v_secret,'{right_end}',to_jsonb(v_new_right),true);
  v_secret:=jsonb_set(v_secret,'{pass_count}','0'::jsonb,true);
  v_secret:=jsonb_set(v_secret,'{move_count}',to_jsonb(coalesce((v_secret->>'move_count')::integer,0)+1),true);

  update public.game_room_private_state
  set secret_state=v_secret,updated_at=pg_catalog.clock_timestamp()
  where room_id=p_room_id;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(
    p_room_id,p_actor_id,
    case when v_finished then 'domino_finished' else 'domino_play' end,
    jsonb_build_object('tile',v_oriented,'side',v_side,'hand_count',v_count,'finished',v_finished)
  );

  update public.game_rooms
  set status=case when v_finished then 'finished' else 'playing' end,
      game_state=v_state,updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;
  return v_room;
end;
$function$;

create or replace function public.engine_v2_draw_domino(
  p_room_id uuid,
  p_actor_id uuid,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_secret jsonb;
  v_hand jsonb;
  v_boneyard jsonb;
  v_tile jsonb;
  v_left integer;
  v_right integer;
  v_playable boolean:=false;
  v_counts jsonb;
  v_board jsonb;
  v_state jsonb;
  v_feed jsonb;
  v_name text;
begin
  if coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'
  ) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_expected_updated_at is null then
    raise exception 'بيانات السحب غير صالحة.' using errcode='22023';
  end if;
  select * into v_room from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة ثانية.' using errcode='40001';
  end if;
  if v_room.engine_version<>2 or v_room.game_key<>'domino' or v_room.status<>'playing' then
    raise exception 'محرك الدومينو غير نشط.';
  end if;
  if v_room.game_state->'board'->>'current_player_id' is distinct from p_actor_id::text then
    raise exception 'مو دورك بعد.' using errcode='42501';
  end if;
  if not exists(select 1 from public.game_room_players p where p.room_id=p_room_id and p.user_id=p_actor_id) then
    raise exception 'لست عضواً في هذه الغرفة.' using errcode='42501';
  end if;
  select secret_state into v_secret
  from public.game_room_private_state where room_id=p_room_id for update;
  if not found then raise exception 'حالة الدومينو الخاصة غير متاحة.'; end if;

  v_hand:=v_secret->'hands'->p_actor_id::text;
  v_boneyard:=coalesce(v_secret->'boneyard','[]'::jsonb);
  if jsonb_array_length(coalesce(v_secret->'chain','[]'::jsonb))=0 then
    raise exception 'لازم يلعب حامل الدبل ستة أول قطعة قبل السحب.';
  end if;
  if jsonb_array_length(v_boneyard)=0 then
    raise exception 'انتهت قطع السحب؛ مرّر الدور إذا ما عندك حركة.';
  end if;
  v_left:=(v_secret->>'left_end')::integer;
  v_right:=(v_secret->>'right_end')::integer;
  for v_tile in select value from jsonb_array_elements(v_hand)
  loop
    if (v_tile->>0)::integer in (v_left,v_right)
       or (v_tile->>1)::integer in (v_left,v_right) then
      v_playable:=true;
      exit;
    end if;
  end loop;
  if v_playable then
    raise exception 'عندك قطعة تگدر تلعبها؛ لا تسحب.';
  end if;

  v_tile:=v_boneyard->0;
  v_boneyard:=v_boneyard-0;
  v_hand:=v_hand||jsonb_build_array(v_tile);
  v_counts:=jsonb_set(
    v_room.game_state->'board'->'hand_counts',
    array[p_actor_id::text],
    to_jsonb(jsonb_array_length(v_hand)),
    true
  );
  v_board:=v_room.game_state->'board'||jsonb_build_object(
    'hand_counts',v_counts,
    'boneyard_count',jsonb_array_length(v_boneyard),
    'last_move',jsonb_build_object('player_id',p_actor_id::text,'action','draw')
  );
  v_state:=v_room.game_state||jsonb_build_object('board',v_board);
  select display_name into v_name from public.game_room_players where room_id=p_room_id and user_id=p_actor_id;
  v_feed:=coalesce(v_room.game_state->'feed','[]'::jsonb)||jsonb_build_array(v_name||' سحب قطعة.');
  v_state:=jsonb_set(v_state,'{feed}',v_feed,true);

  v_secret:=jsonb_set(v_secret,array['hands',p_actor_id::text],v_hand,true);
  v_secret:=jsonb_set(v_secret,'{boneyard}',v_boneyard,true);
  update public.game_room_private_state
  set secret_state=v_secret,updated_at=pg_catalog.clock_timestamp()
  where room_id=p_room_id;
  update public.game_rooms
  set game_state=v_state,updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(p_room_id,p_actor_id,'domino_draw',
    jsonb_build_object('remaining_boneyard',jsonb_array_length(v_boneyard)));
  return v_room;
end;
$function$;

create or replace function public.engine_v2_pass_domino(
  p_room_id uuid,
  p_actor_id uuid,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_secret jsonb;
  v_hand jsonb;
  v_boneyard jsonb;
  v_tile jsonb;
  v_board jsonb;
  v_state jsonb;
  v_order jsonb;
  v_total integer;
  v_index integer;
  v_passes integer;
  v_left integer;
  v_right integer;
  v_playable boolean:=false;
  v_pips jsonb:='{}'::jsonb;
  v_min_pips integer:=2147483647;
  v_sum integer;
  v_winners jsonb:='[]'::jsonb;
  v_scores jsonb;
  v_feed jsonb;
  v_player record;
  v_status text;
begin
  if coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'
  ) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_expected_updated_at is null then
    raise exception 'بيانات تمرير الدور غير صالحة.' using errcode='22023';
  end if;
  select * into v_room from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة ثانية.' using errcode='40001';
  end if;
  if v_room.engine_version<>2 or v_room.game_key<>'domino' or v_room.status<>'playing' then
    raise exception 'محرك الدومينو غير نشط.';
  end if;
  if v_room.game_state->'board'->>'current_player_id' is distinct from p_actor_id::text then
    raise exception 'مو دورك بعد.' using errcode='42501';
  end if;
  if not exists(select 1 from public.game_room_players p where p.room_id=p_room_id and p.user_id=p_actor_id) then
    raise exception 'لست عضواً في هذه الغرفة.' using errcode='42501';
  end if;
  select secret_state into v_secret
  from public.game_room_private_state where room_id=p_room_id for update;
  if not found then raise exception 'حالة الدومينو الخاصة غير متاحة.'; end if;

  v_hand:=v_secret->'hands'->p_actor_id::text;
  v_boneyard:=coalesce(v_secret->'boneyard','[]'::jsonb);
  if jsonb_array_length(coalesce(v_secret->'chain','[]'::jsonb))=0 then
    raise exception 'لازم يلعب حامل الدبل ستة أول قطعة قبل تمرير الدور.';
  end if;
  v_left:=(v_secret->>'left_end')::integer;
  v_right:=(v_secret->>'right_end')::integer;
  if jsonb_array_length(v_boneyard)>0 then
    raise exception 'لا تگدر تمرّر الدور قبل انتهاء كومة السحب.';
  end if;
  for v_tile in select value from jsonb_array_elements(v_hand)
  loop
    if (v_tile->>0)::integer in (v_left,v_right)
       or (v_tile->>1)::integer in (v_left,v_right) then
      v_playable:=true;
      exit;
    end if;
  end loop;
  if v_playable then
    raise exception 'عندك قطعة قانونية؛ العبها قبل تمرير الدور.';
  end if;

  v_board:=v_room.game_state->'board';
  v_order:=v_secret->'player_order';
  v_total:=jsonb_array_length(v_order);
  v_index:=coalesce((v_board->>'turn_index')::integer,0);
  v_passes:=coalesce((v_secret->>'pass_count')::integer,0)+1;
  if v_index<0 or v_index>=v_total then raise exception 'ترتيب الأدوار غير صالح.'; end if;

  if v_passes>=v_total then
    for v_player in
      select p.user_id from public.game_room_players p where p.room_id=p_room_id
    loop
      select coalesce(sum((piece.value->>0)::integer+(piece.value->>1)::integer),0)::integer
      into v_sum
      from jsonb_array_elements(v_secret->'hands'->v_player.user_id::text) as piece(value);
      v_pips:=v_pips||jsonb_build_object(v_player.user_id::text,v_sum);
      if v_sum<v_min_pips then
        v_min_pips:=v_sum;
        v_winners:=jsonb_build_array(v_player.user_id::text);
      elsif v_sum=v_min_pips then
        v_winners:=v_winners||jsonb_build_array(v_player.user_id::text);
      end if;
    end loop;

    v_scores:=coalesce(v_room.game_state->'scores','{}'::jsonb);
    if jsonb_array_length(v_winners)=1 then
      v_scores:=jsonb_set(
        v_scores,
        array[v_winners->>0],
        to_jsonb(coalesce((v_scores->> (v_winners->>0))::integer,0)+1),
        true
      );
    end if;
    v_board:=v_board||jsonb_build_object(
      'pass_count',v_passes,'winner_ids',v_winners,
      'pip_totals',v_pips,'finish_reason','blocked',
      'current_player_id',null
    );
    v_feed:=coalesce(v_room.game_state->'feed','[]'::jsonb)
      ||jsonb_build_array('انسدت اللعبة بعد تمرير جميع اللاعبين. الفائز أقل مجموع نقاط.');
    v_state:=v_room.game_state||jsonb_build_object(
      'phase','finished','board',v_board,'scores',v_scores,'feed',v_feed
    );
    v_status:='finished';
    update public.game_room_private_state
    set secret_state=jsonb_set(secret_state,'{pass_count}',to_jsonb(v_passes),true),
        updated_at=pg_catalog.clock_timestamp()
    where room_id=p_room_id;
  else
    v_index:=(v_index+1)%v_total;
    v_board:=v_board||jsonb_build_object(
      'pass_count',v_passes,
      'current_player_id',v_order->>v_index,
      'turn_index',v_index,
      'last_move',jsonb_build_object('player_id',p_actor_id::text,'action','pass')
    );
    v_feed:=coalesce(v_room.game_state->'feed','[]'::jsonb)
      ||jsonb_build_array('لا توجد حركة قانونية؛ مرّر اللاعب دوره.');
    v_state:=v_room.game_state||jsonb_build_object(
      'turn',v_index,'board',v_board,'feed',v_feed
    );
    v_status:='playing';
    v_secret:=jsonb_set(v_secret,'{pass_count}',to_jsonb(v_passes),true);
    update public.game_room_private_state
    set secret_state=v_secret,updated_at=pg_catalog.clock_timestamp()
    where room_id=p_room_id;
  end if;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(
    p_room_id,p_actor_id,
    case when v_status='finished' then 'domino_finished' else 'domino_pass' end,
    jsonb_build_object('consecutive_passes',v_passes,'finished',v_status='finished')
  );

  update public.game_rooms
  set status=v_status,game_state=v_state,updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;
  return v_room;
end;
$function$;

create or replace function public.engine_v2_restart_domino_game(
  p_room_id uuid,
  p_actor_id uuid,
  p_deal jsonb,
  p_boneyard jsonb,
  p_starting_player uuid,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
begin
  if coalesce(
    nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role'
  ) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  select * into v_room from public.game_rooms where id=p_room_id;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  return public.engine_v2_start_domino_game(
    p_room_id,p_actor_id,p_deal,p_boneyard,p_starting_player,p_expected_updated_at,true
  );
end;
$function$;

create or replace function public.reconcile_domino_after_player_leave()
returns trigger
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_board jsonb;
  v_state jsonb;
begin
  select * into v_room from public.game_rooms where id=old.room_id for update;
  if not found or v_room.engine_version<>2 or v_room.game_key<>'domino'
     or v_room.status<>'playing' then
    return old;
  end if;
  v_board:=coalesce(v_room.game_state->'board','{}'::jsonb)
    ||jsonb_build_object('finish_reason','player_left','current_player_id',null);
  v_state:=v_room.game_state||jsonb_build_object(
    'phase','finished','board',v_board,
    'feed',coalesce(v_room.game_state->'feed','[]'::jsonb)
      ||jsonb_build_array('انتهت الجولة لأن لاعباً غادر الغرفة.')
  );
  update public.game_rooms
  set status='finished',game_state=v_state,updated_at=pg_catalog.clock_timestamp()
  where id=old.room_id;
  delete from public.game_room_private_state where room_id=old.room_id;
  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(old.room_id,old.user_id,'domino_player_left',jsonb_build_object('round_ended',true));
  return old;
end;
$function$;

drop trigger if exists game_room_players_reconcile_domino on public.game_room_players;
create trigger game_room_players_reconcile_domino
after delete on public.game_room_players
for each row execute function public.reconcile_domino_after_player_leave();

revoke all on function public.engine_v2_start_domino_game(uuid,uuid,jsonb,jsonb,uuid,timestamptz,boolean)
  from public,anon,authenticated;
revoke all on function public.engine_v2_get_domino_hand(uuid,uuid)
  from public,anon,authenticated;
revoke all on function public.engine_v2_play_domino(uuid,uuid,integer,integer,text,timestamptz)
  from public,anon,authenticated;
revoke all on function public.engine_v2_draw_domino(uuid,uuid,timestamptz)
  from public,anon,authenticated;
revoke all on function public.engine_v2_pass_domino(uuid,uuid,timestamptz)
  from public,anon,authenticated;
revoke all on function public.engine_v2_restart_domino_game(uuid,uuid,jsonb,jsonb,uuid,timestamptz)
  from public,anon,authenticated;
revoke all on function public.reconcile_domino_after_player_leave()
  from public,anon,authenticated;

grant execute on function public.engine_v2_start_domino_game(uuid,uuid,jsonb,jsonb,uuid,timestamptz,boolean)
  to service_role;
grant execute on function public.engine_v2_get_domino_hand(uuid,uuid)
  to service_role;
grant execute on function public.engine_v2_play_domino(uuid,uuid,integer,integer,text,timestamptz)
  to service_role;
grant execute on function public.engine_v2_draw_domino(uuid,uuid,timestamptz)
  to service_role;
grant execute on function public.engine_v2_pass_domino(uuid,uuid,timestamptz)
  to service_role;
grant execute on function public.engine_v2_restart_domino_game(uuid,uuid,jsonb,jsonb,uuid,timestamptz)
  to service_role;

commit;
